import React, { useContext } from 'react';
import HomeAllSection from './Home/HomeAllSection';
import AboutAllSection from './About/AboutAllSection';
import { useLocation } from 'react-router-dom';
import { LanguageContext } from '../Context/LanguageContext';

const EnglishContent = () => {
    const location = useLocation();
    const { activeLanguage } = useContext(LanguageContext);

    return (
        <>
            {location.pathname === '/home' && (
                activeLanguage === 'english' ? <HomeAllSection /> : <p>សូមជ្រើសរើសភាសាខ្មែរ</p>
            )}
            {location.pathname === '/about' && (
                activeLanguage === 'english' ? <AboutAllSection /> : <p>សូមជ្រើសរើសភាសាខ្មែរ</p>
            )}
        </>
    );
};

export default EnglishContent;
